var n = parseInt(prompt("Entrez un nombre compris entre 1 et 10 :"));
if (isNaN(n) || n < 1 || n > 10) {
  alert("Nombre invalide : il doit être compris entre 1 et 10.");
} else {
  for (var i = 1; i <= n; i++) {
    console.log("affichage no " + i + " : ceci est un exercice");
  }
  alert("Affichage terminé");
}
